#!/usr/bin/env python3
"""Generate third_party/occt/occt.BUILD from an OCCT source tree.

Reads each toolkit's PACKAGES / EXTERNLIB / (per-package) FILES manifests and
emits one cc_library per toolkit in the SUBSET list. Also emits a `:occt`
aggregate and a cc_shared_library for the whole set.

Usage:
    python3 gen_bazel.py <path/to/OCCT-src-root> > occt.BUILD
"""
from __future__ import annotations

import os
import sys
from pathlib import Path

# Modeling + data-exchange subset. No visualization (TKV3d, TKOpenGl, etc.),
# no TKService/Font, no Draw/IVtk, no TCL.
SUBSET = [
    # FoundationClasses
    "TKernel", "TKMath",
    # ModelingData
    "TKG2d", "TKG3d", "TKGeomBase", "TKBRep",
    # ModelingAlgorithms
    "TKGeomAlgo", "TKTopAlgo", "TKPrim",
    "TKBO", "TKBool", "TKHLR", "TKFillet", "TKOffset", "TKFeat",
    "TKMesh", "TKShHealing",
    # DataExchange / XCAF
    "TKDE", "TKXSBase",
    "TKDESTEP", "TKDESTL", "TKDEIGES", "TKDEGLTF", "TKDEOBJ", "TKDEPLY",
    "TKDECascade", "TKDEVRML",
    "TKRWMesh",
    "TKXCAF", "TKLCAF", "TKCAF",
    "TKCDF",
    "TKBinL", "TKBin", "TKBinXCAF", "TKBinTObj",
    "TKStdL", "TKStd",
    "TKVCAF",
    "TKTObj",
    # Visualization (required by DE/XCAF toolkits' EXTERNLIB). Compiled without
    # OpenGL/FreeType/FreeImage/TBB — unused symbols remain but never linked
    # into a program that doesn't call them.
    "TKService", "TKV3d",
    # XML persistence (required by TKDECascade).
    "TKXmlL", "TKXml", "TKXmlTObj", "TKXmlXCAF",
]

# CSF_* → linkopts on linux. Everything else is elided (Windows/GL/X11/etc.).
CSF_LINUX = {
    "CSF_ThreadLibs": ["-lpthread", "-lrt"],
    "CSF_dl": ["-ldl"],
    # Not used in this subset but harmless if they ever show up:
    "CSF_MMGR": [],
    "CSF_androidlog": [],
    # Windows-only — drop:
    "CSF_advapi32": [], "CSF_gdi32": [], "CSF_user32": [],
    "CSF_shell32": [], "CSF_wsock32": [], "CSF_psapi": [],
    "CSF_winmm": [], "CSF_d3d9": [],
    # GL/text/image/mesh 3rd-party we explicitly don't want:
    "CSF_OpenGlLibs": [], "CSF_OpenGlesLibs": [], "CSF_XwLibs": [],
    "CSF_FREETYPE": [], "CSF_TBB": [], "CSF_Draco": [],
    "CSF_VTK": [], "CSF_FFmpeg": [], "CSF_FreeImagePlus": [],
    "CSF_fontconfig": [], "CSF_OpenVR": [],
    "CSF_Appkit": [], "CSF_IOKit": [],
    # 3rd-party we deliberately omit — disabled via missing HAVE_*:
    "CSF_RapidJSON": [], "CSF_OpenVR": [],
    # TBB per-toolkit aliases (also empty since HAVE_TBB is off):
    "CSF_TBBTKBRep": [], "CSF_TBBTKernel": [],
    # X11/macOS graphics service libs — not linking anyway:
    "CSF_dpsLibs": [], "CSF_XmuLibs": [], "CSF_objc": [],
}

HEADER_EXTS = (".hxx", ".h", ".lxx", ".pxx", ".hpp", ".gxx")
SOURCE_EXTS = (".cxx", ".cpp", ".c")


def read_lines(path: Path) -> list[str]:
    if not path.exists():
        return []
    out = []
    for raw in path.read_text(errors="replace").splitlines():
        line = raw.split("#", 1)[0].strip()
        if line:
            out.append(line)
    return out


def toolkit_manifest(occt_root: Path, tk: str) -> tuple[list[str], list[str]]:
    packages = read_lines(occt_root / "src" / tk / "PACKAGES")
    externlib = read_lines(occt_root / "src" / tk / "EXTERNLIB")
    if not packages:
        packages = [tk]
    return packages, externlib


def package_files(occt_root: Path, pkg: str) -> list[str]:
    files_manifest = occt_root / "src" / pkg / "FILES"
    listed = read_lines(files_manifest)
    if listed:
        return listed
    # Fallback: glob directory.
    pkg_dir = occt_root / "src" / pkg
    if not pkg_dir.is_dir():
        return []
    return sorted(f.name for f in pkg_dir.iterdir() if f.is_file())


def split_files(pkg: str, files: list[str]) -> tuple[list[str], list[str]]:
    """Return (sources, headers) as POSIX-relative paths `src/<pkg>/<name>`."""
    srcs, hdrs = [], []
    for fn in files:
        low = fn.lower()
        path = f"src/{pkg}/{fn}"
        if low.endswith(SOURCE_EXTS):
            # Skip Objective-C++ etc.
            if low.endswith(".mm"):
                continue
            srcs.append(path)
        elif low.endswith(HEADER_EXTS):
            hdrs.append(path)
    return srcs, hdrs


def bzl_list(items, indent: int = 8) -> str:
    if not items:
        return "[]"
    pad = " " * indent
    inner = "\n".join(f'{pad}"{x}",' for x in items)
    return "[\n" + inner + f"\n{' ' * (indent - 4)}]"


def emit(occt_root: Path) -> str:
    subset_set = set(SUBSET)
    chunks: list[str] = []

    chunks.append(
        '# AUTO-GENERATED by third_party/occt/gen_bazel.py. Edit the generator, not this file.\n'
        '\n'
        'load("@rules_cc//cc:defs.bzl", "cc_library", "cc_shared_library")\n'
        '\n'
        'package(default_visibility = ["//visibility:public"])\n'
        '\n'
        '# Common OCCT-wide compile options. OCC_CONVERT_SIGNALS makes\n'
        '# Standard_Failure translate SIGSEGV/SIGFPE into exceptions.\n'
        'OCCT_COPTS = [\n'
        '    "-DOCC_CONVERT_SIGNALS",\n'
        # HAVE_* macros use #ifdef in OCCT sources, so leaving them undefined
        # elides freetype/rapidjson/tbb/draco/vtk/gl/xlib/ffmpeg/openvr code.
        '    "-DOCCT_NO_PLUGINS",\n'
        '    "-Wno-deprecated-declarations",\n'
        '    "-Wno-unused-but-set-variable",\n'
        '    "-Wno-unused-variable",\n'
        '    "-Wno-unused-function",\n'
        '    "-Wno-sign-compare",\n'
        '    "-Wno-narrowing",\n'
        '    "-Wno-switch",\n'
        '    "-Wno-reorder",\n'
        '    "-Wno-parentheses",\n'
        ']\n'
    )

    # A header-only library exposing *every* package's headers with its dir on
    # the include path. OCCT's build model assumes any toolkit can include any
    # other toolkit's headers; rather than reverse-engineer per-toolkit needs
    # we mirror that model here.
    all_pkg_dirs: list[str] = []
    all_hdr_globs: list[str] = []
    src_dir = occt_root / "src"
    for pkg in sorted(p.name for p in src_dir.iterdir() if p.is_dir()):
        # Skip toolkit "packages" that are actually toolkits (TK*) and the
        # Shaders pseudo-package (handled separately).
        if pkg.startswith("TK") or pkg == "Shaders":
            continue
        all_pkg_dirs.append(f"src/{pkg}")
        all_hdr_globs.append(f"src/{pkg}/*.hxx")
        all_hdr_globs.append(f"src/{pkg}/*.lxx")
        all_hdr_globs.append(f"src/{pkg}/*.h")
        all_hdr_globs.append(f"src/{pkg}/*.hpp")
        all_hdr_globs.append(f"src/{pkg}/*.pxx")
        all_hdr_globs.append(f"src/{pkg}/*.gxx")
    chunks.append(
        'cc_library(\n'
        '    name = "occt_all_hdrs",\n'
        '    hdrs = glob(' + bzl_list(all_hdr_globs) + ', allow_empty = True),\n'
        '    includes = ' + bzl_list(all_pkg_dirs) + ',\n'
        ')\n'
    )

    # Shader .pxx files live outside any toolkit (src/Shaders) but are
    # included via relative paths (#include "../Shaders/X.pxx") from Graphic3d.
    # Expose them as a single textual-headers lib every TK* depends on.
    shaders_dir = occt_root / "src" / "Shaders"
    shader_files = []
    if shaders_dir.is_dir():
        for f in sorted(shaders_dir.iterdir()):
            if f.is_file() and f.suffix.lower() in (".pxx", ".glsl", ".fs", ".vs", ".hxx", ".h"):
                shader_files.append(f"src/Shaders/{f.name}")
    chunks.append(
        'cc_library(\n'
        '    name = "occt_shaders",\n'
        '    textual_hdrs = ' + bzl_list(shader_files) + ',\n'
        '    hdrs = ' + bzl_list([f for f in shader_files if f.endswith(('.hxx', '.h'))]) + ',\n'
        '    includes = ["src/Shaders", "src"],\n'
        ')\n'
    )

    # Build per-toolkit rules.
    for tk in SUBSET:
        packages, externlib = toolkit_manifest(occt_root, tk)

        all_srcs: list[str] = []
        all_hdrs: list[str] = []
        include_dirs: list[str] = []
        for pkg in packages:
            files = package_files(occt_root, pkg)
            srcs, hdrs = split_files(pkg, files)
            all_srcs.extend(srcs)
            all_hdrs.extend(hdrs)
            if hdrs:
                include_dirs.append(f"src/{pkg}")

        # Toolkit-level pch / extra headers.
        tk_dir = occt_root / "src" / tk
        for extra in ("TKernel_pch.hxx",):
            p = tk_dir / extra
            if p.exists():
                all_hdrs.append(f"src/{tk}/{extra}")

        deps: list[str] = []
        linkopts: list[str] = []
        for ext in externlib:
            if ext in subset_set:
                deps.append(f":{ext}")
            elif ext.startswith("CSF_"):
                linkopts.extend(CSF_LINUX.get(ext, []))
            elif ext.startswith("TK"):
                # Out-of-subset toolkit dependency → warn only in comment.
                deps.append(f"# MISSING: {ext}")
            else:
                deps.append(f"# UNKNOWN: {ext}")

        # Dedupe while preserving order.
        def uniq(xs):
            seen, out = set(), []
            for x in xs:
                if x not in seen:
                    seen.add(x); out.append(x)
            return out

        deps = uniq(deps)
        # Every toolkit needs the generated headers (Standard_Version.hxx, ...)
        # and the union of all package headers (OCCT's cross-toolkit includes).
        deps.append("@@//third_party/occt:generated_hdrs")
        deps.append(":occt_shaders")
        deps.append(":occt_all_hdrs")
        linkopts = uniq(linkopts)
        include_dirs = uniq(include_dirs)

        chunks.append(f'# ---- {tk} ----')
        chunks.append(
            f'cc_library(\n'
            f'    name = "{tk}",\n'
            f'    srcs = {bzl_list(sorted(set(all_srcs)))},\n'
            f'    hdrs = {bzl_list(sorted(set(all_hdrs)))},\n'
            f'    includes = {bzl_list(include_dirs)},\n'
            f'    copts = OCCT_COPTS,\n'
            f'    linkopts = {bzl_list(linkopts)},\n'
            f'    deps = {bzl_list([d for d in deps if not d.startswith("#")])},\n'
            f'    alwayslink = True,\n'
            f')\n'
        )

    # Aggregate meta-library.
    chunks.append('# Aggregate — link this to pull every toolkit in the subset.')
    chunks.append(
        'cc_library(\n'
        '    name = "occt",\n'
        '    deps = ' + bzl_list([f":{tk}" for tk in SUBSET], indent=8) + ',\n'
        ')\n'
    )

    # Shared .so for FFI / scripting consumers.
    chunks.append(
        'cc_shared_library(\n'
        '    name = "libocct",\n'
        '    shared_lib_name = "libocct.so",\n'
        '    deps = [":occt"],\n'
        ')\n'
    )

    return "\n".join(chunks)


def main() -> int:
    if len(sys.argv) != 2:
        print(__doc__, file=sys.stderr)
        return 2
    root = Path(sys.argv[1]).resolve()
    if not (root / "src").is_dir():
        print(f"not an OCCT source root: {root}", file=sys.stderr)
        return 2
    sys.stdout.write(emit(root))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
